import pty, os

def run_pty(args, env_extra=None):
    master, slave = pty.openpty()
    pid = os.fork()
    if pid == 0:
        os.close(master)
        os.dup2(slave, 0)
        os.dup2(slave, 1)
        os.dup2(slave, 2)
        os.close(slave)
        env = dict(os.environ)
        env['TERM'] = 'xterm-256color'
        if env_extra:
            env.update(env_extra)
        os.execve('./executable', ['./executable'] + args, env)
    else:
        os.close(slave)
        output = b''
        while True:
            try:
                data = os.read(master, 1024)
                if not data:
                    break
                output += data
            except OSError:
                break
        os.close(master)
        return output.decode('utf-8', errors='replace')

print('A. test.json .a:', repr(run_pty(['test.json', '.a'])))
print('B. nonexistent.json .a:', repr(run_pty(['nonexistent.json', '.a'])))
print('C. .a:', repr(run_pty(['.a'])))
