    return all(is_primitive(x) for x in val.values())

def format_json(val, indent=0, is_root=True, parent_type=None, no_inline=False):
    if val is None:
        return "null"
    if isinstance(val, bool):
        return "true" if val else "false"
    if isinstance(val, (int, float)):
        return str(val)
