class UndefinedType:
    def __repr__(self): return 'undefined'
    def __str__(self): return 'undefined'
    def __bool__(self): return False

Undefined = UndefinedType()

class SkipSymbol:
    def __repr__(self): return 'Symbol(skip)'
    def __str__(self): return 'Symbol(skip)'

Skip = SkipSymbol()

def is_falsely(x):
    if isinstance(x, Box): x = x._val
    return x is False or x is None or x is Undefined

def js_type_name(x):
    if isinstance(x, Box): x = x._val
    if x is Undefined: return 'undefined'
    if x is None: return 'object'
    if isinstance(x, bool): return 'boolean'
    if isinstance(x, (int, float)): return 'number'
    if isinstance(x, str): return 'string'
    if isinstance(x, list): return 'array'
    if isinstance(x, dict): return 'object'
    return type(x).__name__

class Box:
    def __init__(self, val):
        if isinstance(val, Box): val = val._val
        self._val = val

    def unwrap(self):
        return self._val

    def __repr__(self):
        return repr(self._val)

    def __bool__(self):
        return bool(self._val) and self._val is not Undefined

    def __len__(self):
        if isinstance(self._val, (list, str, dict)):
            return len(self._val)
        return 0

    def __iter__(self):
        if isinstance(self._val, list):
            for item in self._val: yield Box(item)
        elif isinstance(self._val, dict):
            for k in self._val: yield Box(k)

    def __getitem__(self, key):
        if isinstance(key, Box): key = key._val
        val = self._val
        if isinstance(val, dict):
            if key in val: return Box(val[key])
            return Box(Undefined)
        elif isinstance(val, (list, tuple)):
            if isinstance(key, int):
                if 0 <= key < len(val) or -len(val) <= key < 0:
                    return Box(val[key])
            return Box(Undefined)
        elif isinstance(val, str):
            if isinstance(key, int):
                if 0 <= key < len(val) or -len(val) <= key < 0:
                    return Box(val[key])
            return Box(Undefined)
        return Box(Undefined)

    def __getattr__(self, name):
        if name.startswith('_'): raise AttributeError(name)
        val = self._val
        if name == 'length':
            if isinstance(val, (list, str, dict)): return Box(len(val))
            return Box(Undefined)
        if name == 'map': return lambda fn: Box(js_map(fn, val))
        if name == 'filter': return lambda fn: Box(js_filter(fn, val))
        if name == 'reduce': return lambda fn, init=Undefined: Box(js_reduce(fn, val, init))
        if name == 'find': return lambda fn: Box(js_find(fn, val))
        if name == 'flatMap': return lambda fn: Box(js_flat_map(fn, val))
        if name == 'slice': return lambda start=0, end=None: Box(js_slice(val, start, end))
        if name == 'join': return lambda sep=',': Box((sep.unwrap() if isinstance(sep, Box) else sep).join(str(x.unwrap() if isinstance(x, Box) else x) for x in val) if isinstance(val, list) else str(val))
        if name == 'toUpperCase': return lambda: Box(val.upper() if isinstance(val, str) else str(val).upper())
        if name == 'toLowerCase': return lambda: Box(val.lower() if isinstance(val, str) else str(val).lower())
        if name == 'trim': return lambda: Box(val.strip() if isinstance(val, str) else str(val).strip())
        if name == 'split': return lambda sep=None: Box(val.split(sep.unwrap() if isinstance(sep, Box) else sep) if isinstance(val, str) else [])
        if name == 'sort': return lambda fn=None: Box(js_sort(val, fn))
        if name == 'reverse': return lambda: Box(list(reversed(val)) if isinstance(val, list) else val)
        if name == 'includes': return lambda item: Box((item.unwrap() if isinstance(item, Box) else item) in val)
        if name == 'indexOf': return lambda item: Box(val.index(item.unwrap() if isinstance(item, Box) else item) if (item.unwrap() if isinstance(item, Box) else item) in val else -1)
        if name == 'keys': return lambda: Box(list(val.keys()) if isinstance(val, dict) else Undefined)
        if name == 'values': return lambda: Box(list(val.values()) if isinstance(val, dict) else Undefined)
        if name == 'entries': return lambda: Box([list(x) for x in val.items()] if isinstance(val, dict) else Undefined)

        if isinstance(val, dict):
            if name in val: return Box(val[name])
            return Box(Undefined)

        return Box(Undefined)

def js_map(fn, x):
    x_val = x.unwrap() if isinstance(x, Box) else x
    if isinstance(x_val, list):
        res = []
        for i, item in enumerate(x_val):
            item_box = Box(item)
            try: res_i = fn(item_box, Box(i))
            except TypeError: res_i = fn(item_box)
            res.append(res_i.unwrap() if isinstance(res_i, Box) else res_i)
        return res
    res = fn(Box(x_val))
    return res.unwrap() if isinstance(res, Box) else res

def js_filter(fn, x):
    x_val = x.unwrap() if isinstance(x, Box) else x
    if isinstance(x_val, list):
        res = []
        for i, item in enumerate(x_val):
            item_box = Box(item)
            try: keep = fn(item_box, Box(i))
            except TypeError: keep = fn(item_box)
            keep_val = keep.unwrap() if isinstance(keep, Box) else keep
            if not is_falsely(keep_val): res.append(item)
        return res
    keep = fn(Box(x_val))
    keep_val = keep.unwrap() if isinstance(keep, Box) else keep
    return Skip if is_falsely(keep_val) else x_val

def js_reduce(fn, x, init=Undefined):
    x_val = x.unwrap() if isinstance(x, Box) else x
    if isinstance(x_val, list):
        if not x_val and init is Undefined: raise Exception("Reduce of empty array with no initial value")
        acc = init if init is not Undefined else x_val[0]
        start_idx = 0 if init is not Undefined else 1
        for i in range(start_idx, len(x_val)):
            acc_box = Box(acc) if not isinstance(acc, Box) else acc
            item_box = Box(x_val[i])
            try: acc = fn(acc_box, item_box, Box(i))
            except TypeError: acc = fn(acc_box, item_box)
            if isinstance(acc, Box): acc = acc.unwrap()
        return acc
    raise Exception(f"Cannot reduce {js_type_name(x_val)}")

def js_find(fn, x):
    x_val = x.unwrap() if isinstance(x, Box) else x
    if isinstance(x_val, list):
        for i, item in enumerate(x_val):
            item_box = Box(item)
            try: found = fn(item_box, Box(i))
            except TypeError: found = fn(item_box)
            found_val = found.unwrap() if isinstance(found, Box) else found
            if not is_falsely(found_val): return item
        return Undefined
    raise Exception(f"Cannot find in {js_type_name(x_val)}")

def js_flat_map(fn, x):
    x_val = x.unwrap() if isinstance(x, Box) else x
    if isinstance(x_val, list):
        res = []
        for i, item in enumerate(x_val):
            item_box = Box(item)
            try: mapped = fn(item_box, Box(i))
            except TypeError: mapped = fn(item_box)
            mapped_val = mapped.unwrap() if isinstance(mapped, Box) else mapped
            if isinstance(mapped_val, list): res.extend(mapped_val)
            else: res.append(mapped_val)
        return res
    raise Exception(f"Cannot flatMap {js_type_name(x_val)}")

def js_slice(x, start=0, end=None):
    x_val = x.unwrap() if isinstance(x, Box) else x
    if isinstance(start, Box): start = start.unwrap()
    if isinstance(end, Box): end = end.unwrap()
    if isinstance(x_val, (list, str)):
        if end is None or end is Undefined: return x_val[start:]
        return x_val[start:end]
    return Undefined

def js_sort(x, fn=None):
    x_val = x.unwrap() if isinstance(x, Box) else x
    if isinstance(x_val, list):
        if fn is not None:
            return sorted(x_val, key=lambda i: fn(Box(i)).unwrap() if isinstance(fn(Box(i)), Box) else fn(Box(i)))
