class UndefinedType:
    def __repr__(self): return 'undefined'
    def __str__(self): return 'undefined'
    def __bool__(self): return False

Undefined = UndefinedType()

class SkipSymbol:
    def __repr__(self): return 'Symbol(skip)'
    def __str__(self): return 'Symbol(skip)'

Skip = SkipSymbol()

def is_falsely(x):
    if isinstance(x, Box): x = x._val
    return x is False or x is None or x is Undefined

def js_type_name(x):
    if isinstance(x, Box): x = x._val
    if x is Undefined: return 'undefined'
    if x is None: return 'object'
    if isinstance(x, bool): return 'boolean'
    if isinstance(x, (int, float)): return 'number'
    if isinstance(x, str): return 'string'
    if isinstance(x, list): return 'array'
    if isinstance(x, dict): return 'object'
    return type(x).__name__

class Box:
    def __init__(self, val):
        if isinstance(val, Box): val = val._val
        self._val = val

    def unwrap(self):
        return self._val

    def __repr__(self):
        return repr(self._val)

    def __bool__(self):
        return bool(self._val) and self._val is not Undefined

    def __len__(self):
        if isinstance(self._val, (list, str, dict)):
            return len(self._val)
        return 0

    def __iter__(self):
        if isinstance(self._val, list):
            for item in self._val: yield Box(item)
        elif isinstance(self._val, dict):
            for k in self._val: yield Box(k)

    def __getitem__(self, key):
        if isinstance(key, Box): key = key._val
        val = self._val
        if isinstance(val, dict):
            if key in val: return Box(val[key])
            return Box(Undefined)
        elif isinstance(val, (list, tuple)):
            if isinstance(key, int):
                if 0 <= key < len(val) or -len(val) <= key < 0:
                    return Box(val[key])
            return Box(Undefined)
        elif isinstance(val, str):
            if isinstance(key, int):
                if 0 <= key < len(val) or -len(val) <= key < 0:
                    return Box(val[key])
            return Box(Undefined)
        return Box(Undefined)

    def __getattr__(self, name):
        if name.startswith('_'): raise AttributeError(name)
        val = self._val
        if name == 'length':
            if isinstance(val, (list, str, dict)): return Box(len(val))
            return Box(Undefined)
        if name == 'map': return lambda fn: Box(js_map(fn, val))
        if name == 'filter': return lambda fn: Box(js_filter(fn, val))
        if name == 'reduce': return lambda fn, init=Undefined: Box(js_reduce(fn, val, init))
        if name == 'find': return lambda fn: Box(js_find(fn, val))
        if name == 'flatMap': return lambda fn: Box(js_flat_map(fn, val))
        if name == 'slice': return lambda start=0, end=None: Box(js_slice(val, start, end))
        if name == 'join': return lambda sep=',': Box((sep.unwrap() if isinstance(sep, Box) else sep).join(str(x.unwrap() if isinstance(x, Box) else x) for x in val) if isinstance(val, list) else str(val))
        if name == 'toUpperCase': return lambda: Box(val.upper() if isinstance(val, str) else str(val).upper())
        if name == 'toLowerCase': return lambda: Box(val.lower() if isinstance(val, str) else str(val).lower())
        if name == 'trim': return lambda: Box(val.strip() if isinstance(val, str) else str(val).strip())
        if name == 'split': return lambda sep=None: Box(val.split(sep.unwrap() if isinstance(sep, Box) else sep) if isinstance(val, str) else [])
        if name == 'sort': return lambda fn=None: Box(js_sort(val, fn))
        if name == 'reverse': return lambda: Box(list(reversed(val)) if isinstance(val, list) else val)
        if name == 'includes': return lambda item: Box((item.unwrap() if isinstance(item, Box) else item) in val)
        if name == 'indexOf': return lambda item: Box(val.index(item.unwrap() if isinstance(item, Box) else item) if (item.unwrap() if isinstance(item, Box) else item) in val else -1)
        if name == 'keys': return lambda: Box(list(val.keys()) if isinstance(val, dict) else Undefined)
        if name == 'values': return lambda: Box(list(val.values()) if isinstance(val, dict) else Undefined)
        if name == 'entries': return lambda: Box([list(x) for x in val.items()] if isinstance(val, dict) else Undefined)

        if isinstance(val, dict):
            if name in val: return Box(val[name])
            return Box(Undefined)

        return Box(Undefined)

def js_map(fn, x):
    x_val = x.unwrap() if isinstance(x, Box) else x
    if isinstance(x_val, list):
        res = []
        for i, item in enumerate(x_val):
            item_box = Box(item)
            try: res_i = fn(item_box, Box(i))
            except TypeError: res_i = fn(item_box)
            res.append(res_i.unwrap() if isinstance(res_i, Box) else res_i)
        return res
    res = fn(Box(x_val))
    return res.unwrap() if isinstance(res, Box) else res

def js_filter(fn, x):
    x_val = x.unwrap() if isinstance(x, Box) else x
    if isinstance(x_val, list):
        res = []
        for i, item in enumerate(x_val):
            item_box = Box(item)
            try: keep = fn(item_box, Box(i))
            except TypeError: keep = fn(item_box)
            keep_val = keep.unwrap() if isinstance(keep, Box) else keep
            if not is_falsely(keep_val): res.append(item)
        return res
    keep = fn(Box(x_val))
    keep_val = keep.unwrap() if isinstance(keep, Box) else keep
    return Skip if is_falsely(keep_val) else x_val

def js_reduce(fn, x, init=Undefined):
    x_val = x.unwrap() if isinstance(x, Box) else x
    if isinstance(x_val, list):
        if not x_val and init is Undefined: raise Exception("Reduce of empty array with no initial value")
        acc = init if init is not Undefined else x_val[0]
        start_idx = 0 if init is not Undefined else 1
        for i in range(start_idx, len(x_val)):
            acc_box = Box(acc) if not isinstance(acc, Box) else acc
            item_box = Box(x_val[i])
            try: acc = fn(acc_box, item_box, Box(i))
            except TypeError: acc = fn(acc_box, item_box)
            if isinstance(acc, Box): acc = acc.unwrap()
        return acc
    raise Exception(f"Cannot reduce {js_type_name(x_val)}")

def js_find(fn, x):
    x_val = x.unwrap() if isinstance(x, Box) else x
    if isinstance(x_val, list):
        for i, item in enumerate(x_val):
            item_box = Box(item)
            try: found = fn(item_box, Box(i))
            except TypeError: found = fn(item_box)
            found_val = found.unwrap() if isinstance(found, Box) else found
            if not is_falsely(found_val): return item
        return Undefined
    raise Exception(f"Cannot find in {js_type_name(x_val)}")

def js_flat_map(fn, x):
    x_val = x.unwrap() if isinstance(x, Box) else x
    if isinstance(x_val, list):
        res = []
        for i, item in enumerate(x_val):
            item_box = Box(item)
            try: mapped = fn(item_box, Box(i))
            except TypeError: mapped = fn(item_box)
            mapped_val = mapped.unwrap() if isinstance(mapped, Box) else mapped
            if isinstance(mapped_val, list): res.extend(mapped_val)
            else: res.append(mapped_val)
        return res
    raise Exception(f"Cannot flatMap {js_type_name(x_val)}")

def js_slice(x, start=0, end=None):
    x_val = x.unwrap() if isinstance(x, Box) else x
    if isinstance(start, Box): start = start.unwrap()
    if isinstance(end, Box): end = end.unwrap()
    if isinstance(x_val, (list, str)):
        if end is None or end is Undefined: return x_val[start:]
        return x_val[start:end]
    return Undefined

def js_sort(x, fn=None):
    x_val = x.unwrap() if isinstance(x, Box) else x
    if isinstance(x_val, list):
        if fn is not None:
            return sorted(x_val, key=lambda i: fn(Box(i)).unwrap() if isinstance(fn(Box(i)), Box) else fn(Box(i)))
        return sorted(x_val, key=lambda i: (0 if isinstance(i, (int, float)) else 1, str(i)))
    raise Exception(f"Cannot sort {js_type_name(x_val)}")

def js_keys(x):
    x_val = x.unwrap() if isinstance(x, Box) else x
    if isinstance(x_val, dict): return list(x_val.keys())
    raise Exception(f"Cannot get keys of {js_type_name(x_val)}")

def js_values(x):
    x_val = x.unwrap() if isinstance(x, Box) else x
    if isinstance(x_val, dict): return list(x_val.values())
    raise Exception(f"Cannot get values of {js_type_name(x_val)}")

def js_len(x):
    x_val = x.unwrap() if isinstance(x, Box) else x
    if isinstance(x_val, (list, str, dict)): return len(x_val)
    raise Exception(f"Cannot get length of {js_type_name(x_val)}")

def js_uniq(x):
    x_val = x.unwrap() if isinstance(x, Box) else x
    if isinstance(x_val, list):
        res = []
        for item in x_val:
            if item not in res: res.append(item)
        return res
    raise Exception(f"Cannot get unique values of {js_type_name(x_val)}")

def js_sort_keys(x):
    x_val = x.unwrap() if isinstance(x, Box) else x
    if isinstance(x_val, list): return [js_sort_keys(i) for i in x_val]
    if isinstance(x_val, dict):
        res = {}
        for k in sorted(x_val.keys()): res[k] = js_sort_keys(x_val[k])
        return res
    return x_val

def js_group_by(fn):
    def closure(x):
        x_val = x.unwrap() if isinstance(x, Box) else x
        grouped = {}
        for item in x_val:
            item_box = Box(item)
            key = fn(item_box).unwrap() if callable(fn) else item_box[fn].unwrap()
            key_str = str(key)
            if key_str not in grouped: grouped[key_str] = []
            grouped[key_str].append(item)
        return grouped
    return closure

def js_chunk(size):
    if isinstance(size, Box): size = size.unwrap()
    def closure(x):
        x_val = x.unwrap() if isinstance(x, Box) else x
        res = []
        i = 0
        while i < len(x_val):
            res.append(x_val[i:i+size])
            i += size
        return res
    return closure

def js_zip(*args):
    unwrapped = [a.unwrap() if isinstance(a, Box) else a for a in args]
    min_len = min(len(a) for a in unwrapped)
    res = []
    for i in range(min_len):
        res.append([a[i] for a in unwrapped])
    return res

def js_flatten(x):
    x_val = x.unwrap() if isinstance(x, Box) else x
    if isinstance(x_val, list):
        res = []
        for item in x_val:
            if isinstance(item, list): res.extend(item)
            else: res.append(item)
        return res
    raise Exception(f"Cannot flatten {js_type_name(x_val)}")

def js_reverse(x):
    x_val = x.unwrap() if isinstance(x, Box) else x
    if isinstance(x_val, list): return list(reversed(x_val))
    raise Exception(f"Cannot reverse {js_type_name(x_val)}")

def js_del(key):
    if isinstance(key, Box): key = key.unwrap()
    def closure(x):
        x_val = x.unwrap() if isinstance(x, Box) else x
        if isinstance(x_val, list):
            copy = list(x_val)
            if 0 <= key < len(copy): copy.pop(key)
            return copy
        if isinstance(x_val, dict):
            copy = dict(x_val)
            copy.pop(key, None)
            return copy
        raise Exception(f"Cannot delete key from {js_type_name(x_val)}")
    return closure

def js_walk(fn):
    def recurse(value, key=None):
        val_unwrapped = value.unwrap() if isinstance(value, Box) else value
        if isinstance(val_unwrapped, list):
            mapped = [recurse(v, i) for i, v in enumerate(val_unwrapped)]
            res = fn(Box(mapped), Box(key) if key is not None else Undefined)
            return res.unwrap() if isinstance(res, Box) else res
        elif isinstance(val_unwrapped, dict):
            result = {}
            for k, v in val_unwrapped.items():
                result[k] = recurse(v, k)
            res = fn(Box(result), Box(key) if key is not None else Undefined)
            return res.unwrap() if isinstance(res, Box) else res
        else:
            res = fn(Box(val_unwrapped), Box(key) if key is not None else Undefined)
            return res.unwrap() if isinstance(res, Box) else res
    return lambda x: recurse(x)

def js_list(x):
    x_val = x.unwrap() if isinstance(x, Box) else x
    if isinstance(x_val, list):
        for y in x_val: print(y)
        return Skip
    raise Exception(f"Cannot list {js_type_name(x_val)}")

def js_apply(fn, *args):
    if isinstance(fn, Box): fn = fn.unwrap()
    if callable(fn): return fn(*args)
    return fn

# Formatting & Inlining
def is_primitive(v):
    return v is None or isinstance(v, (bool, int, float, str))

def is_inlinable_array(val):
    if not isinstance(val, list) or not val: return False
    return all(is_primitive(x) for x in val)

def is_inlinable_object(val):
    if not isinstance(val, dict) or not val: return False
    return all(is_primitive(x) for x in val.values())

def format_json(val, indent=0, is_root=True, parent_type=None, no_inline=False, theme_id="0", is_tty=False):
    t = THEME_MAP.get(theme_id, {}) if is_tty else {}
    p = t.get('punct', '')
    p_end = '\x1b[0m' if p else ''
    k_color = t.get('key', '')
    k_end = '\x1b[0m' if k_color else ''
    s_color = t.get('string', '')
    s_end = '\x1b[0m' if s_color else ''
    num_color = t.get('number', '')
    num_end = '\x1b[0m' if num_color else ''
    b_color = t.get('bool', '')
    b_end = '\x1b[0m' if b_color else ''
    nl_color = t.get('null', '')
    nl_end = '\x1b[0m' if nl_color else ''

    if val is None:
        return f"{nl_color}null{nl_end}"
    if isinstance(val, bool):
        s_bool = "true" if val else "false"
        return f"{b_color}{s_bool}{b_end}"
    if isinstance(val, (int, float)):
        return f"{num_color}{val}{num_end}"
    if isinstance(val, str):
        return f"{s_color}{json.dumps(val)}{s_end}"

    if isinstance(val, dict):
        if not val: return f"{p}{{{p_end}"
        if not is_root and not no_inline and parent_type == 'list' and is_inlinable_object(val):
            inner_parts = []
            for k, v in val.items():
                k_str = f"{k_color}{json.dumps(k)}{k_end}"
                v_str = format_json(v, indent=indent, is_root=False, parent_type='dict', no_inline=no_inline, theme_id=theme_id, is_tty=is_tty)
                inner_parts.append(f"{k_str}{p}:{p_end} {v_str}")
            inner = f"{p},{p_end} ".join(inner_parts)
            return f"{p}{{{p_end} {inner} {p}}}{p_end}"

        lines = [f"{p}{{{p_end}"]
        items = list(val.items())
        for i, (k, v) in enumerate(items):
            comma = f"{p},{p_end}" if i < len(items) - 1 else ""
            k_str = f"{k_color}{json.dumps(k)}{k_end}"
            v_str = format_json(v, indent + 2, is_root=False, parent_type='dict', no_inline=no_inline, theme_id=theme_id, is_tty=is_tty)
            lines.append(" " * (indent + 2) + f"{k_str}{p}:{p_end} {v_str}{comma}")
        lines.append(" " * indent + f"{p}}}{p_end}")
        return "\n".join(lines)

    if isinstance(val, list):
        if not val: return f"{p}[{p_end}"
        if not is_root and not no_inline and is_inlinable_array(val):
            inner = f"{p},{p_end} ".join(format_json(v, indent=indent, is_root=False, parent_type='list', no_inline=no_inline, theme_id=theme_id, is_tty=is_tty) for v in val)
            return f"{p}[{p_end} {inner} {p}]{p_end}"

        lines = [f"{p}[{p_end}"]
        for i, v in enumerate(val):
            comma = f"{p},{p_end}" if i < len(val) - 1 else ""
            v_str = format_json(v, indent + 2, is_root=False, parent_type='list', no_inline=no_inline, theme_id=theme_id, is_tty=is_tty)
            lines.append(" " * (indent + 2) + f"{v_str}{comma}")
        lines.append(" " * indent + f"{p}]{p_end}")
        return "\n".join(lines)

    return str(val)

def strip_json_comments_and_trailing_commas(s):
    result = []
    i = 0
    n = len(s)
    in_string = False
    string_char = None

    while i < n:
        c = s[i]
        if in_string:
            result.append(c)
            if c == '\\':
                if i + 1 < n:
                    result.append(s[i+1])
                    i += 1
            elif c == string_char:
                in_string = False
            i += 1
            continue

        if c in ('"', "'"):
            in_string = True
            string_char = c
            result.append(c)
            i += 1
            continue

        if c == '/' and i + 1 < n and s[i+1] == '/':
            i += 2
            while i < n and s[i] != '\n': i += 1
            continue

        if c == '/' and i + 1 < n and s[i+1] == '*':
            i += 2
            while i + 1 < n and not (s[i] == '*' and s[i+1] == '/'): i += 1
            i += 2
            continue

        if c == ',':
            j = i + 1
            while j < n and s[j] in ' \t\r\n': j += 1
            if j < n and s[j] in (']', '}'):
                i += 1
                continue

        result.append(c)
        i += 1

    cleaned = "".join(result)
    cleaned = re.sub(r'\bNaN\b', 'null', cleaned)
    cleaned = re.sub(r'\bInfinity\b', '1e9999', cleaned)
    cleaned = re.sub(r'-\bInfinity\b', '-1e9999', cleaned)
    return cleaned

# Main CLI execution
def main():
    args = sys.argv[1:]

    # Check shell completion env
    if 'COMP_LINE' in os.environ or 'COMP_ZSH' in os.environ or 'COMP_FISH' in os.environ:
        # Handle shell completion
        line = os.environ.get('COMP_LINE', os.environ.get('COMP_ZSH', os.environ.get('COMP_FISH', '')))
        words = line.split()
        cur = words[-1] if words else ''
        files = glob.glob(f"{cur}*")
        flags = ['--help', '--raw', '--slurp', '--themes', '--version', '--yaml', '--toml', '--strict', '--no-inline']
        if 'COMP_ZSH' in os.environ:
            for f in files:
                if os.path.isdir(f): f += '/'
                print(f"{f}\t{f}\tfile")
            if cur.startswith('-'):
                for fl in flags:
                    if fl.startswith(cur):
                        print(f"{fl}\t{fl}\tflag")
        else:
            if cur.startswith('-'):
                for fl in flags:
                    if fl.startswith(cur): print(fl)
            else:
                for f in files:
                    if os.path.isdir(f): f += '/'
                    print(f)
        sys.exit(0)

    # Parse flags
    is_help = False
    is_version = False
    is_themes = False
    comp_shell = None
    is_raw = False
    is_slurp = False
    is_yaml = False
    is_toml = False
    is_strict = False
    is_no_inline = False
