    i = 0
    while i < len(args):
        a = args[i]
        if a in ('-h', '--help'): is_help = True
        elif a in ('-v', '--version'): is_version = True
        elif a == '--themes': is_themes = True
        elif a == '--comp':
            if i + 1 < len(args):
                comp_shell = args[i+1]
                i += 1
            else:
                print("flag needs an argument: -comp", file=sys.stderr)
                sys.exit(2)
        elif a.startswith('--comp='): comp_shell = a.split('=', 1)[1]
        elif a in ('-r', '--raw'): is_raw = True
        elif a in ('-s', '--slurp'): is_slurp = True
        elif a == '--yaml': is_yaml = True
        elif a == '--toml': is_toml = True
        elif a == '--strict': is_strict = True
        elif a == '--no-inline': is_no_inline = True
        elif a == '--game-of-life': is_game_of_life = True
        else: expr_args.append(a)
        i += 1

    if is_help:
        sys.stdout.write(HELP_TEXT[1:])
        sys.exit(0)

    if is_version:
        sys.stdout.write(f"{VERSION}\n")
        sys.exit(0)

    if is_themes:
