#!/usr/bin/env python3
import sys, os, re, json, math, base64, glob

VERSION = "39.2.0"

HELP_TEXT = """
  fx 39.2.0
    Terminal JSON viewer

  Usage
    fx data.json
    fx data.json .field
    curl ... | fx

  Flags
    -h, --help            print help
