    def __radd__(self, o): return Box(self._u(o) + self._val)
    def __sub__(self, o): return Box(self._val - self._u(o))
    def __rsub__(self, o): return Box(self._u(o) - self._val)
    def __mul__(self, o): return Box(self._val * self._u(o))
    def __rmul__(self, o): return Box(self._u(o) * self._val)
    def __truediv__(self, o): return Box(self._val / self._u(o))
    def __rtruediv__(self, o): return Box(self._u(o) / self._val)
    def __floordiv__(self, o): return Box(self._val // self._u(o))
    def __mod__(self, o): return Box(self._val % self._u(o))
    def __gt__(self, o): return self._val > self._u(o)
    def __lt__(self, o): return self._val < self._u(o)
    def __ge__(self, o): return self._val >= self._u(o)
    def __le__(self, o): return self._val <= self._u(o)
    def __eq__(self, o): return self._val == self._u(o)
