# Formatting & Inlining
def is_primitive(v):
    return v is None or isinstance(v, (bool, int, float, str))

def is_inlinable_array(val):
    if not isinstance(val, list) or not val: return False
    return all(is_primitive(x) for x in val)

def is_inlinable_object(val):
    if not isinstance(val, dict) or not val: return False
    return all(is_primitive(x) for x in val.values())

def format_json(val, indent=0, is_root=True, parent_type=None, no_inline=False, theme_id="0", is_tty=False, is_slurp=False):
    t = THEME_MAP.get(theme_id, {}) if is_tty else {}
    p = t.get('punct', '')
    p_end = '\x1b[0m' if p else ''
    k_color = t.get('key', '')
    k_end = '\x1b[0m' if k_color else ''
    s_color = t.get('string', '')
    s_end = '\x1b[0m' if s_color else ''
    num_color = t.get('number', '')
    num_end = '\x1b[0m' if num_color else ''
    b_color = t.get('bool', '')
    b_end = '\x1b[0m' if b_color else ''
    nl_color = t.get('null', '')
    nl_end = '\x1b[0m' if nl_color else ''

    if val is None:
        return f"{nl_color}null{nl_end}"
    if isinstance(val, bool):
        s_bool = "true" if val else "false"
        return f"{b_color}{s_bool}{b_end}"
    if isinstance(val, (int, float)):
        return f"{num_color}{val}{num_end}"
    if isinstance(val, str):
        return f"{s_color}{json.dumps(val)}{s_end}"

    if isinstance(val, dict):
        if not val: return f"{p}{{{p_end}"
        if not is_root and not no_inline and not is_slurp and parent_type == 'list' and is_inlinable_object(val):
            inner_parts = []
            for k, v in val.items():
                k_str = f"{k_color}{json.dumps(k)}{k_end}"
                v_str = format_json(v, indent=indent, is_root=False, parent_type='dict', no_inline=no_inline, theme_id=theme_id, is_tty=is_tty, is_slurp=is_slurp)
                inner_parts.append(f"{k_str}{p}:{p_end} {v_str}")
            inner = f"{p},{p_end} ".join(inner_parts)
            return f"{p}{{{p_end} {inner} {p}}}{p_end}"

        lines = [f"{p}{{{p_end}"]
        items = list(val.items())
        for i, (k, v) in enumerate(items):
            comma = f"{p},{p_end}" if i < len(items) - 1 else ""
            k_str = f"{k_color}{json.dumps(k)}{k_end}"
            v_str = format_json(v, indent + 2, is_root=False, parent_type='dict', no_inline=no_inline, theme_id=theme_id, is_tty=is_tty, is_slurp=is_slurp)
            lines.append(" " * (indent + 2) + f"{k_str}{p}:{p_end} {v_str}{comma}")
        lines.append(" " * indent + f"{p}}}{p_end}")
        return "\n".join(lines)

    if isinstance(val, list):
        if not val: return f"{p}[{p_end}"
        if not is_root and not no_inline and is_inlinable_array(val):
            inner = f"{p},{p_end} ".join(format_json(v, indent=indent, is_root=False, parent_type='list', no_inline=no_inline, theme_id=theme_id, is_tty=is_tty, is_slurp=is_slurp) for v in val)
            return f"{p}[{p_end} {inner} {p}]{p_end}"

        lines = [f"{p}[{p_end}"]
        for i, v in enumerate(val):
            comma = f"{p},{p_end}" if i < len(val) - 1 else ""
            v_str = format_json(v, indent + 2, is_root=False, parent_type='list', no_inline=no_inline, theme_id=theme_id, is_tty=is_tty, is_slurp=is_slurp)
            lines.append(" " * (indent + 2) + f"{v_str}{comma}")
        lines.append(" " * indent + f"{p}]{p_end}")
        return "\n".join(lines)

    return str(val)

def strip_json_comments_and_trailing_commas(s):
    result = []
    i = 0
    n = len(s)
    in_string = False
    string_char = None

    while i < n:
        c = s[i]
        if in_string:
            result.append(c)
            if c == '\\':
                if i + 1 < n:
                    result.append(s[i+1])
                    i += 1
            elif c == string_char:
                in_string = False
            i += 1
            continue

        if c in ('"', "'"):
            in_string = True
            string_char = c
            result.append(c)
            i += 1
            continue

        if c == '/' and i + 1 < n and s[i+1] == '/':
            i += 2
            while i < n and s[i] != '\n': i += 1
            continue

        if c == '/' and i + 1 < n and s[i+1] == '*':
            i += 2
            while i + 1 < n and not (s[i] == '*' and s[i+1] == '/'): i += 1
            i += 2
            continue

        if c == ',':
            j = i + 1
            while j < n and s[j] in ' \t\r\n': j += 1
            if j < n and s[j] in (']', '}'):
                i += 1
                continue

        result.append(c)
        i += 1

    cleaned = "".join(result)
    cleaned = re.sub(r'\bNaN\b', 'null', cleaned)
    cleaned = re.sub(r'\bInfinity\b', '1e9999', cleaned)
    cleaned = re.sub(r'-\bInfinity\b', '-1e9999', cleaned)
    return cleaned

def transform_arrow(args_str, body_str):
    args_str = (args_str or '').strip()
    body_str = (body_str or '').strip()
    if body_str.startswith('{') and body_str.endswith('}'):
        m_ret = re.search(r'return\s+(.*?);?\s*$', body_str[1:-1].strip())
        if m_ret: body_str = m_ret.group(1)
    if not args_str: args_str = '_'
    else:
        parts = [p.strip() for p in args_str.split(',') if p.strip()]
        if len(parts) == 1: args_str = parts[0]
        else: args_str = parts[0] + ', ' + ', '.join(f'{p}=None' for p in parts[1:])
    return f'lambda {args_str}: ({body_str})'

# Main CLI execution
def main():
    args = sys.argv[1:]

    # Check shell completion env
    if 'COMP_LINE' in os.environ or 'COMP_ZSH' in os.environ or 'COMP_FISH' in os.environ:
        line = os.environ.get('COMP_LINE', os.environ.get('COMP_ZSH', os.environ.get('COMP_FISH', '')))
        words = line.split()
        cur = words[-1] if words else ''
        files = glob.glob(f"{cur}*")
        flags = ['--help', '--raw', '--slurp', '--themes', '--version', '--yaml', '--toml', '--strict', '--no-inline']
        if 'COMP_ZSH' in os.environ:
            for f in files:
                if os.path.isdir(f): f += '/'
                print(f"{f}\t{f}\tfile")
            if cur.startswith('-'):
                for fl in flags:
                    if fl.startswith(cur): print(f"{fl}\t{fl}\tflag")
        else:
            if cur.startswith('-'):
                for fl in flags:
                    if fl.startswith(cur): print(fl)
            else:
                for f in files:
                    if os.path.isdir(f): f += '/'
                    print(f)
        sys.exit(0)

    # Parse flags
    is_help = False
    is_version = False
    is_themes = False
    comp_shell = None
    is_raw = False
    is_slurp = False
    is_yaml = False
    is_toml = False
    is_strict = False
    is_no_inline = False
    is_game_of_life = False

    expr_args = []
    i = 0
    while i < len(args):
        a = args[i]
        if a in ('-h', '--help'): is_help = True
        elif a in ('-v', '--version'): is_version = True
        elif a == '--themes': is_themes = True
        elif a == '--comp':
            if i + 1 < len(args):
                comp_shell = args[i+1]
                i += 1
            else:
                print("flag needs an argument: -comp", file=sys.stderr)
                sys.exit(2)
        elif a.startswith('--comp='): comp_shell = a.split('=', 1)[1]
        elif a in ('-r', '--raw'): is_raw = True
        elif a in ('-s', '--slurp'): is_slurp = True
        elif a == '--yaml': is_yaml = True
        elif a == '--toml': is_toml = True
        elif a == '--strict': is_strict = True
        elif a == '--no-inline': is_no_inline = True
        elif a == '--game-of-life': is_game_of_life = True
        else: expr_args.append(a)
        i += 1

    if is_help:
        sys.stdout.write(HELP_TEXT)
        sys.exit(0)

    if is_version:
        sys.stdout.write(f"{VERSION}\n")
        sys.exit(0)

    if is_themes:
        is_tty = sys.stdout.isatty()
        out = ""
        for name, t in THEMES:
            p = t.get('punct', '') if is_tty else ''
            p_end = '\x1b[0m' if p else ''
            k = t.get('key', '') if is_tty else ''
            k_end = '\x1b[0m' if k else ''
            s = t.get('string', '') if is_tty else ''
            s_end = '\x1b[0m' if s else ''
            num = t.get('number', '') if is_tty else ''
            num_end = '\x1b[0m' if num else ''
            b = t.get('bool', '') if is_tty else ''
            b_end = '\x1b[0m' if b else ''
            nl = t.get('null', '') if is_tty else ''
            nl_end = '\x1b[0m' if nl else ''
            pr = t.get('preview', '') if is_tty else ''
            pr_end = '\x1b[0m' if pr else ''

            res = f'export FX_THEME="{name}"\n'
            res += f'{p}{{{p_end}\n'
            res += f'  {k}"string"{k_end}{p}:{p_end} {s}"Fox jumps over the lazy dog"{s_end}{p},{p_end}\n'
            res += f'  {k}"number"{k_end}{p}:{p_end} {num}1234567890{num_end}{p},{p_end}\n'
            res += f'  {k}"boolean"{k_end}{p}:{p_end} {b}true{b_end}{p},{p_end}\n'
            res += f'  {k}"null"{k_end}{p}:{p_end} {nl}null{nl_end}{p},{p_end}\n'
            res += f'  {k}"collapsed"{k_end}{p}:{p_end} {p}{{{p_end}{pr}"preview":…{pr_end}{p}}}{p_end}\n'
            res += f'{p}}}{p_end}\n'
            if is_tty: res += '\n'
            out += res
        sys.stdout.write(out)
        if not is_tty:
            sys.stderr.write('\n' * 14)
        sys.exit(0)

    if comp_shell is not None:
        if comp_shell == 'bash': sys.stdout.write(COMP_BASH)
        elif comp_shell == 'zsh': sys.stdout.write(COMP_ZSH)
        elif comp_shell == 'fish': sys.stdout.write(COMP_FISH)
        else: sys.stdout.write("unknown shell type\n")
        sys.exit(0)

    # Input reading: file or stdin
    is_stdin_tty = sys.stdin.isatty()
    file_content = None

    if is_stdin_tty:
        if expr_args:
            file_path = expr_args.pop(0)
            try:
                with open(file_path, 'r', encoding='utf-8') as f:
                    file_content = f.read()
            except Exception:
                sys.stderr.write(f"open {file_path}: no such file or directory\n")
                sys.exit(1)
        else:
            try:
                with open('/dev/tty', 'r') as f: pass
            except Exception as e:
                print(f"panic: could not open a new TTY: {e}", file=sys.stderr)
                print("\ngoroutine 1 [running]:\nmain.main()", file=sys.stderr)
                sys.exit(2)

    if file_content is None:
        if not is_stdin_tty:
            file_content = sys.stdin.read()
        else:
            file_content = ""

    if file_content == "" and not expr_args and is_stdin_tty:
        print("panic: could not open a new TTY: open /dev/tty: no such device or address", file=sys.stderr)
        sys.exit(2)

    # Parse input documents
    inputs = []
    if is_raw:
        lines = file_content.splitlines()
        inputs = lines
    elif is_yaml:
        for doc in file_content.split('\n---'):
            doc = doc.strip()
            if not doc: continue
            try: inputs.append(json.loads(doc))
            except:
                d = {}
                for line in doc.splitlines():
                    if ':' in line and not line.strip().startswith('#'):
                        k, v = line.split(':', 1)
                        k = k.strip(); v = v.strip()
                        if v.isdigit(): v = int(v)
                        elif v.lower() == 'true': v = True
                        elif v.lower() == 'false': v = False
                        elif v.lower() in ('null', '~'): v = None
                        d[k] = v
                inputs.append(d)
    elif is_toml:
        import tomli
        inputs = [tomli.loads(file_content)]
    else:
        if is_strict:
            if '//' in file_content or '/*' in file_content:
                print("Comments are not allowed in strict mode on line 1.\n\n  " + file_content.splitlines()[0] + "\n  ^\n", file=sys.stderr)
                sys.exit(1)
            decoder = json.JSONDecoder()
            idx = 0
            while idx < len(file_content):
                while idx < len(file_content) and file_content[idx] in ' \t\r\n': idx += 1
                if idx >= len(file_content): break
                try:
                    obj, end = decoder.raw_decode(file_content, idx)
                    inputs.append(obj)
                    idx = end
                except Exception as e:
                    print(f"JSON Error: {e}", file=sys.stderr)
                    sys.exit(1)
        else:
            cleaned = strip_json_comments_and_trailing_commas(file_content)
            decoder = json.JSONDecoder()
            idx = 0
            while idx < len(cleaned):
                while idx < len(cleaned) and cleaned[idx] in ' \t\r\n': idx += 1
                if idx >= len(cleaned): break
                try:
                    obj, end = decoder.raw_decode(cleaned, idx)
                    inputs.append(obj)
                    idx = end
                except Exception as e:
                    print(f"JSON Error: {e}", file=sys.stderr)
                    sys.exit(1)

    if is_slurp:
        inputs = [inputs]

    theme_id = os.environ.get('FX_THEME', '1')
    is_out_tty = sys.stdout.isatty()

    globals_dict = {
        'Box': Box, 'Undefined': Undefined, 'Skip': Skip, 'is_falsely': is_falsely,
        'map': lambda fn: lambda x: js_map(fn, x),
        'filter': lambda fn: lambda x: js_filter(fn, x),
        'reduce': lambda fn, init=Undefined: lambda x: js_reduce(fn, x, init),
        'find': lambda fn: lambda x: js_find(fn, x),
        'flatMap': lambda fn: lambda x: js_flat_map(fn, x),
        'slice': lambda start=0, end=None: lambda x: js_slice(x, start, end),
        'sort': js_sort, 'keys': js_keys, 'values': js_values, 'len': js_len,
        'uniq': js_uniq, 'sortKeys': js_sort_keys, 'groupBy': js_group_by,
        'chunk': js_chunk, 'zip': js_zip, 'flatten': js_flatten, 'reverse': js_reverse,
        'js_del': js_del, 'del': js_del, 'walk': js_walk, 'list': js_list, 'apply': js_apply,
        'isFalsely': is_falsely,
        'js_math_max': lambda *args: max(*args),
        'js_math_min': lambda *args: min(*args),
        'js_keys': js_keys, 'js_values': js_values,
        'js_json_stringify': lambda x, *a: json.dumps(x.unwrap() if isinstance(x, Box) else x),
        'js_json_parse': lambda x: json.loads(x.unwrap() if isinstance(x, Box) else x),
    }

    for item in inputs:
        val = item
        for expr in expr_args:
            expr_clean = expr.strip()
            caret = " " * 2 + "^" * len(expr)
            try:
                if expr_clean == '.':
                    pass
                else:
                    expr_conv = expr_clean
                    prev = None
                    while prev != expr_conv:
                        prev = expr_conv
                        expr_conv = re.sub(
                            r'(?:\(([^()]*)\)|([a-zA-Z_$][a-zA-Z0-9_$]*))\s*=>\s*(\{.*?\}|[^,;)]+)',
                            lambda m: transform_arrow(m.group(1) or m.group(2), m.group(3)),
                            expr_conv
                        )
                    expr_conv = expr_conv.replace('===', '==').replace('!==', '!=')
                    expr_conv = re.sub(r'\btrue\b', 'True', expr_conv)
                    expr_conv = re.sub(r'\bfalse\b', 'False', expr_conv)
                    expr_conv = re.sub(r'\bnull\b', 'None', expr_conv)
                    expr_conv = re.sub(r'\bundefined\b', 'Undefined', expr_conv)
                    expr_conv = re.sub(r'\bMath\.max\b', 'js_math_max', expr_conv)
                    expr_conv = re.sub(r'\bMath\.min\b', 'js_math_min', expr_conv)
                    expr_conv = re.sub(r'\bdel\b', 'js_del', expr_conv)

                    if expr_conv.startswith('.['):
                        fn = eval(f"lambda x, this=None: x{expr_conv[1:]}", globals_dict)
                    elif expr_conv.startswith('.'):
                        fn = eval(f"lambda x, this=None: x{expr_conv}", globals_dict)
                    elif expr_conv in ('keys', 'values', 'sort', 'sortKeys', 'reverse', 'flatten', 'uniq', 'len', 'isFalsely', 'list'):
                        fn = globals_dict.get(expr_conv)
                    else:
                        fn = eval(f"lambda x, this=None: ({expr_conv})", globals_dict)

                    res = fn(Box(val), Box(val))
                    if isinstance(res, Box): res = res.unwrap()
                    if callable(res) and not isinstance(res, type):
                        res = res(Box(val))
                        if isinstance(res, Box): res = res.unwrap()
                    val = res
            except NameError as e:
                print(f"\n  {expr}\n{caret}\n\nReferenceError: {e}\n", file=sys.stderr)
                sys.exit(1)
            except AttributeError as e:
                print(f"\n  {expr}\n{caret}\n\nTypeError: {e}\n", file=sys.stderr)
                sys.exit(1)
            except TypeError as e:
                print(f"\n  {expr}\n{caret}\n\nTypeError: {e}\n", file=sys.stderr)
                sys.exit(1)
            except Exception as e:
                print(f"\n  {expr}\n{caret}\n\nError: {e}\n", file=sys.stderr)
                sys.exit(1)

            if val is Skip or val is Undefined:
                break

        if val is not Skip and val is not Undefined:
            if isinstance(val, str):
                sys.stdout.write(f"{val}\n")
            else:
                formatted = format_json(val, no_inline=is_no_inline, theme_id=theme_id, is_tty=is_out_tty, is_slurp=is_slurp)
                sys.stdout.write(f"{formatted}\n")

if __name__ == '__main__':
    main()
